Settings.Decl:
type Settings struct {
	SubjectID string `db:"subject_id"`
	// Title names the subject in the admin and e-mail. Events use their own
	// title when it is empty.
	Title string `db:"title"`
	// Open switches registration on.
	Open bool `db:"is_open"`
	// Capacity is the number of places (adults and children); 0 is unlimited.
	Capacity int `db:"capacity"`
	// ClosesAt is the registration deadline. Without one, registration for an
	// event closes when it starts.
	ClosesAt      *time.Time `db:"closes_at"`
	AdultPrice    Cents      `db:"adult_price"`
	ChildPrice    Cents      `db:"child_price"`
	AllowChildren bool       `db:"allow_children"`
	// UpdatedAt and UpdatedBy are the last change by an editor.
	UpdatedAt time.Time `db:"updated_at"`
	UpdatedBy db.Ref    `db:"updated_by"`
	// Texts are what registrants read, per language. SaveSettings stores the
	// languages given and keeps the others.
	Texts []SubjectText
}

Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/registrations.LookupView */}}
{{/* Starting point generated by WebThings: find a registration by its code. */}}
<main id="content">
    <h1>{{.Title}}</h1>

    {{if .NotFound}}<p>No registration has the code {{.Code}}.</p>{{end}}

    {{form_open .Form}}
        {{form_field .Form "code" nil}}
        <button type="submit">Look up</button>
    {{form_close}}
</main>

{{/* @dot github.com/donseba/go-webthings/modules/registrations.RegistrationView */}}
{{/* Starting point generated by WebThings: one registration with its cancel form. */}}
<main id="content">
    <h1>{{.Subject.Title}}</h1>

    {{if eq .Result "registered"}}<p>Thank you, you are registered. We sent you a confirmation.</p>{{end}}

    {{/* When the event takes place (frontend.When); zero for other subjects. */}}
    {{with .Subject.When}}{{if not .IsZero}}
        <p>{{if .AllDay}}{{dateRange .Start .End "full"}}{{else if .SameDay}}{{date .Start "full"}} · {{timeRange .Start .End}}{{else}}{{date .Start "full"}}, {{time .Start}} – {{date .End "full"}}, {{time .End}}{{end}}</p>
    {{end}}{{end}}

    <dl>
        <dt>Code</dt><dd>{{.Code}}</dd>
        <dt>Name</dt><dd>{{.Name}}</dd>
        <dt>Adults</dt><dd>{{.Adults}}</dd>
        {{if .Children}}<dt>Children</dt><dd>{{.Children}}</dd>{{end}}
        {{if .Total}}<dt>Total</dt><dd>{{money .Total .Currency}} ({{.Payment}})</dd>{{end}}
        {{with .Notes}}<dt>Your notes</dt><dd>{{.}}</dd>{{end}}
        <dt>Registered on</dt><dd>{{date .CreatedAt}}</dd>
    </dl>

    {{with .PaymentLink}}<p>Payment: {{.}}</p>{{end}}
    {{with .Info}}<div class="registration-info">{{.}}</div>{{end}}

    {{/* The cancel form returns the visitor here, to the element with the id {{.Key}}. */}}
    <section id="{{.Key}}">
        {{if eq .Result "cancelled"}}<p>Your registration is cancelled.</p>{{end}}
        {{if eq .Result "invalid"}}<p>That e-mail address does not match this registration.</p>{{end}}
        {{if eq .Result "throttled"}}<p>Too many attempts. Please try again later.</p>{{end}}

        {{if .Cancelled}}
            <p>This registration is cancelled.</p>
        {{else}}
            {{form_open .Form}}
                {{form_field .Form "code" nil}}
                {{form_field .Form "email" nil}}

                <button type="submit">Cancel registration</button>
            {{form_close}}
        {{end}}
    </section>
</main>

Components.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/registrations.FormView */}}
{{/* The sign-up box of a subject: prices, places, the result of the last post and the form: {{registrationForm "signup" .ID}}. */}}
{{if .Configured}}
<section class="wt-registration" id="{{.Key}}" aria-labelledby="{{.Key}}-registration-title">
    <h2 class="wt-registration__title" id="{{.Key}}-registration-title">{{tl localizer "Sign up"}}</h2>

    {{with .Result}}
        <p class="wt-notice" role="status">
            {{if eq . "registered"}}{{tl localizer "Thank you, you are registered. We sent you a confirmation."}}
                {{with $.Code}}{{tl localizer "Your registration code is %s." .}}{{end}}
            {{else if eq . "full"}}{{tl localizer "Sorry, there are not enough places left."}}
            {{else if eq . "closed"}}{{tl localizer "Registration is closed."}}
            {{else if eq . "cancelled"}}{{tl localizer "Your registration is cancelled."}}
            {{else if eq . "throttled"}}{{tl localizer "Too many attempts. Please try again later."}}
            {{else}}{{tl localizer "Please check your name, e-mail address and the number of places."}}{{end}}
        </p>
    {{end}}

    <dl class="wt-registration__facts">
        <dt>{{tl localizer "Price"}}</dt>
        <dd>
            {{if .Prices.Free}}{{tl localizer "Free"}}{{else}}{{money .Prices.Adult .Currency}} {{tl localizer "per person"}}{{end}}
            {{if and .AllowChildren .Prices.Child}}<br>{{money .Prices.Child .Currency}} {{tl localizer "per child"}}{{end}}
        </dd>

        {{if .Capacity}}
            <dt>{{tl localizer "Places left"}}</dt>
            <dd>{{if .Full}}{{tl localizer "None"}}{{else}}{{tl localizer "%d of %d" .Left .Capacity}}{{end}}</dd>
        {{end}}

        {{if not .ClosesAt.IsZero}}
            <dt>{{tl localizer "Sign up before"}}</dt>
            <dd>{{date .ClosesAt}}, {{time .ClosesAt}}</dd>
        {{end}}
    </dl>

    {{with .Notes}}<div class="wt-registration__notes">{{.}}</div>{{end}}

    {{if .Open}}
        {{/* The form returns the visitor to the element with the id {{.Key}}. */}}
        {{form_open .Form}}
            {{form_field .Form "subject" nil}}
            {{form_field .Form "name" nil}}
            {{form_field .Form "email" nil}}

            <div class="wt-form__row">
                {{form_field .Form "adults" nil}}
                {{if .AllowChildren}}{{form_field .Form "children" nil}}{{end}}
            </div>

            {{form_field .Form "notes" nil}}

            <button class="wt-button" type="submit">{{tl localizer "Sign up"}}</button>
        {{form_close}}
    {{else if .Full}}
        <p class="wt-notice">{{tl localizer "There are no places left."}}</p>
    {{else}}
        <p class="wt-notice">{{tl localizer "Registration is closed."}}</p>
    {{end}}

    {{with .LookupURL}}
        <p class="wt-meta">{{tl localizer "Already registered?"}} <a href="{{.}}">{{tl localizer "Look up your registration"}}</a></p>
    {{end}}
</section>
{{end}}

Mail.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/registrations.MailView */}}
{{/* Sent to the visitor after registering. */}}
{{define "subject"}}{{tl localizer "Registration"}} {{.Code}}: {{.Subject.Title}}{{end}}

{{define "text"}}
{{tl localizer "Hello %s," .Name}}

{{tl localizer "Thank you for registering for %s." .Subject.Title}}
{{- with .Subject.When}}{{if not .IsZero}}
{{if .AllDay}}{{dateRange .Start .End "full"}}{{else if .SameDay}}{{date .Start "full"}} · {{timeRange .Start .End}}{{else}}{{date .Start "full"}}, {{time .Start}} – {{date .End "full"}}, {{time .End}}{{end}}
{{- end}}{{end}}

{{tl localizer "Registration code"}}: {{.Code}}
{{tl localizer "Adults"}}: {{.Adults}}
{{- if .Children}}
{{tl localizer "Children"}}: {{.Children}}
{{- end}}
{{- if .Total}}
{{tl localizer "Total"}}: {{money .Total .Currency}}
{{- end}}
{{- with .PaymentLink}}

{{tl localizer "Please pay using:"}}
{{.}}
{{- end}}
{{- with .Info}}

{{.}}
{{- end}}
{{- with .URL}}

{{tl localizer "View or cancel your registration:"}}
{{.}}
{{- end}}
{{end}}

{{/* @dot github.com/donseba/go-webthings/modules/registrations.MailView */}}
{{/* Sent to the visitor after cancelling a registration on the site. */}}
{{define "subject"}}{{tl localizer "Registration cancelled"}} {{.Code}}: {{.Subject.Title}}{{end}}

{{define "text"}}
{{tl localizer "Hello %s," .Name}}

{{tl localizer "Your registration for %s is cancelled." .Subject.Title}}

{{tl localizer "Registration code"}}: {{.Code}}
{{- if eq .Payment "paid"}}

{{tl localizer "You already paid; we will contact you about a refund."}}
{{- end}}
{{end}}

Types.Decl:
type Availability struct {
	SubjectID string
	// Configured is true when editors set up registration for the subject,
	// open or not; without it a page shows no sign-up at all.
	Configured bool
	// Open is true while visitors can register: registration is switched on,
	// the deadline has not passed and places are left.
	Open bool
	// Closed is true when registration is switched off or its deadline
	// passed, and for subjects that are not Configured.
	Closed bool
	// Full is true when every place is taken.
	Full bool
	// Capacity is the number of places; 0 is unlimited.
	Capacity int
	// Taken is the number of places registered so far.
	Taken int
	// Left is the number of places left; 0 when Capacity is 0.
	Left int
	// ClosesAt is the deadline in the site's timezone; zero when there is none.
	ClosesAt      time.Time
	AllowChildren bool
	Prices        Prices
	// Currency is the ISO 4217 code of the prices, for {{money .Prices.Adult .Currency}}.
	Currency string
	// Notes are the editor's notes for registrants in the requested language,
	// or in the site's default language, rendered from Markdown.
	Notes template.HTML
	// Action is the address the sign-up form posts to.
	Action string
	// Form is the sign-up form's model (SignupInput) for go-form's
	// template functions, such as {{form_open .Form}} and {{form_field
	// .Form "name" nil}}, with the adults and children at most Left when
	// places are limited; it returns the visitor to the element with the
	// instance key as its id.
	Form form.RenderModel
}

type CancelInput struct {
	Code  string `form:"input,hidden" name:"code"  required:"true" maxLength:"20"  line:"true"`
	Email string `form:"input,email"  name:"email" required:"true" maxLength:"254"             label:"The e-mail address you signed up with" autocomplete:"email"`
}

type Fact struct {
	Label string
	Value string
}

type FormView struct {
	// Key is the instance key.
	Key string
	Availability
	// Result is "registered", "full", "closed", "invalid", "cancelled",
	// "throttled" or "".
	Result string
	// Code is the visitor's registration code after registering here, when
	// the instance is placed on no page of its own.
	Code string
	// LookupURL is the page where visitors look up their registration, or ""
	// when the instance is placed on no page.
	LookupURL string
}

type LookupInput struct {
	Code string `form:"input,text" name:"code" required:"true" maxLength:"20" line:"true" label:"Registration code" placeholder:"K7Q4-9M2X" autocomplete:"off"`
}

type LookupView struct {
	// Title is the title of the page the module is mounted on.
	Title string
	// Action is the address the form sends its code field to, with method get.
	Action string
	// Code is the code that was looked up, if any.
	Code string
	// NotFound is set when no registration has Code.
	NotFound bool
	// Form is the lookup form's model (LookupInput, with Code), sent to
	// Action with method get, for go-form's template functions, such as
	// {{form_open .Form}} and {{form_field .Form "code" nil}}.
	Form form.RenderModel
}

type MailView struct {
	// Subject is what the visitor registered for; Start is set for events.
	Subject  Subject
	Code     string
	Name     string
	Adults   int
	Children int
	// Total is in Currency, for {{money .Total .Currency}}.
	Total    Cents
	Currency string
	// Payment is none, pending, paid or cancelled.
	Payment PaymentStatus
	// PaymentLink is the editor's payment link while payment is pending.
	PaymentLink string
	// Notes are the visitor's own remarks; Info the editor's notes for
	// registrants, as the Markdown they wrote, which reads well as text.
	Notes string
	Info  string
	// URL is the registration's page, to view or cancel it; empty when the
	// module is on no page.
	URL string
}

type NewSubjectView struct {
	Title   string
	BackURL string
	Form    form.RenderModel
	Errors  form.FieldErrors
}

type OverviewRow struct {
	URL   string
	Title string
	Date  string
	// Status is "Open", "Closed" or "Full"; it is translated.
	Status        string
	Registrations int
	Places        string
}

type OverviewView struct {
	Title string
	// Events is set when the subjects are events; rows then have a date.
	Events bool
	// NewURL adds a subject; empty for events and without the right.
	NewURL string
	// TrashURL shows the deleted registrations in the admin's trash.
	TrashURL string
	Rows     []OverviewRow
}

type PaymentStatus string

const (
	// PaymentNone is the status of free registrations.
	PaymentNone PaymentStatus = "none"
	// PaymentPending is the status of new registrations with a total.
	PaymentPending PaymentStatus = "pending"
	// PaymentPaid is set by an editor once the payment came in.
	PaymentPaid PaymentStatus = "paid"
	// PaymentCancelled is set when an unpaid registration is cancelled.
	PaymentCancelled PaymentStatus = "cancelled"
)

type Prices struct {
	Adult Cents
	Child Cents
}

type Registration struct {
	ID        string `db:"id"`
	SubjectID string `db:"subject_id"`
	// Code is the visitor's reference, for example "K7Q4-9M2X".
	Code       string        `db:"code"`
	Name       string        `db:"name"`
	Email      string        `db:"email"`
	Adults     int           `db:"adults"`
	Children   int           `db:"children"`
	Total      Cents         `db:"total"`
	Payment    PaymentStatus `db:"payment_status"`
	Notes      string        `db:"notes"`
	AdminNotes string        `db:"admin_notes"`
	// Locale is the language the visitor registered in.
	Locale      string     `db:"locale"`
	CreatedAt   time.Time  `db:"created_at"`
	CancelledAt *time.Time `db:"cancelled_at"`
	// CreatedBy is the editor who added the registration; empty for visitors.
	CreatedBy db.Ref `db:"created_by"`
	// UpdatedAt and UpdatedBy are the last change, by an editor or, when
	// cancelling, by the visitor (UpdatedBy empty).
	UpdatedAt time.Time `db:"updated_at"`
	UpdatedBy db.Ref    `db:"updated_by"`
	// DeletedAt is set while the registration is in the trash, with
	// DeletedBy.
	DeletedAt *time.Time `db:"deleted_at"`
	DeletedBy db.Ref     `db:"deleted_by"`
}

type RegistrationAdminView struct {
	Title        string
	BackURL      string
	Registration Registration
	// Total is the amount in the admin language, such as "€ 120,00";
	// Payment is the translated payment status.
	Total     string
	Payment   string
	Date      string
	Cancelled string
	// Form changes payment and admin notes; nil without the right.
	Form   *form.RenderModel
	Errors form.FieldErrors
	Cancel *form.RenderModel
	Delete *form.RenderModel
}

type RegistrationView struct {
	// Key is the instance key; results arrive as ?<key>=<result>, and the
	// cancel form returns the visitor to the element with the id Key.
	Key string
	// Title is the title of the page the module is mounted on.
	Title string
	// Subject is what the visitor registered for; Start is set for events.
	Subject  Subject
	Code     string
	Name     string
	Adults   int
	Children int
	// Total is in Currency, for {{money .Total .Currency}}.
	Total    Cents
	Currency string
	// Payment is none, pending, paid or cancelled.
	Payment PaymentStatus
	// PaymentLink is the editor's payment link while payment is pending.
	PaymentLink string
	// Notes are the visitor's own remarks; Info the editor's notes for
	// registrants, in the page's language, rendered from Markdown.
	Notes string
	Info  template.HTML
	// CreatedAt is when the visitor registered, for {{date .CreatedAt}}.
	CreatedAt time.Time
	Cancelled bool
	// CancelAction is the address the cancel form posts to (fields code and
	// email); empty when the registration is cancelled.
	CancelAction string
	// Form is the cancel form's model (CancelInput, with Code) for go-form's
	// template functions, such as {{form_open .Form}} and {{form_field
	// .Form "email" nil}}; the zero value when the registration is
	// cancelled.
	Form form.RenderModel
	// Result is the outcome of the visitor's last post: "registered",
	// "cancelled", "invalid", "throttled" or empty.
	Result string
}

type Service struct {
	// contains unexported fields
}

type Settings struct {
	SubjectID string `db:"subject_id"`
	// Title names the subject in the admin and e-mail. Events use their own
	// title when it is empty.
	Title string `db:"title"`
	// Open switches registration on.
	Open bool `db:"is_open"`
	// Capacity is the number of places (adults and children); 0 is unlimited.
	Capacity int `db:"capacity"`
	// ClosesAt is the registration deadline. Without one, registration for an
	// event closes when it starts.
	ClosesAt      *time.Time `db:"closes_at"`
	AdultPrice    Cents      `db:"adult_price"`
	ChildPrice    Cents      `db:"child_price"`
	AllowChildren bool       `db:"allow_children"`
	// UpdatedAt and UpdatedBy are the last change by an editor.
	UpdatedAt time.Time `db:"updated_at"`
	UpdatedBy db.Ref    `db:"updated_by"`
	// Texts are what registrants read, per language. SaveSettings stores the
	// languages given and keeps the others.
	Texts []SubjectText
}

type SettingsView struct {
	Title   string
	BackURL string
	Form    form.RenderModel
	Errors  form.FieldErrors
	// Tabs switch the language of Texts, what registrants read.
	Tabs       []admin.LocaleTab
	Texts      form.RenderModel
	TextErrors form.FieldErrors
}

type Subject struct {
	ID    string
	Title string
	// Start is when an event starts and End when it ends, in the event's
	// timezone; zero for other subjects. End is zero when the event has none,
	// and the last day of all-day events.
	Start  time.Time
	End    time.Time
	AllDay bool
	// URL is the event's page, when visitors can see it.
	URL string
}

type SubjectText struct {
	Locale string `db:"locale"`
	// Notes are shown with the sign-up form, on the registration page and in
	// the confirmation. They are Markdown.
	Notes string `db:"notes"`
	// PaymentLink is shown while payment is pending, for example a payment
	// request URL or bank details.
	PaymentLink string `db:"payment_link"`
}

type SubjectView struct {
	Title   string
	Date    string
	BackURL string
	// BackLabel names the overview BackURL leads to, as a translation key.
	BackLabel string
	// SettingsURL is empty without the right to change settings.
	SettingsURL string
	// ExportURL is empty without the right to export.
	ExportURL string
	Status    string
	Facts     []Fact
	Rows      []RegistrationRow
	// Registrations, Places and Total count active registrations.
	Registrations int
	Places        int
	Total         string
}

type Summary struct {
	SubjectID     string `db:"subject_id"`
	Registrations int    `db:"registrations"`
	Places        int    `db:"places"`
}
